	["Kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents inside The Stockade."] = "Tötet 10 Gefangene der Defias, 8 Sträflinge der Defias und 8 Aufständische der Defias im Verlies.",
	["Kill 15 Enraged Apparitions and 10 Tormented Souls, then put Anvilmar's spirit to rest."] = "Tötet 15 Wütende Erscheinungen und 10 Gequälte Seelen und bringt dann Ambossars Geist zur Ruhe.",
	["Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."] = "Tötet 20 verseuchte Jungdrachen und kehrt dann zu Betina Bigglezink an der Kapelle des Hoffnungsvollen Lichts zurück.",
	["Kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs."] = "Tötet 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckenszähne.",
	["Kill 8 Ragefire Troggs and 8 Ragefire Shamans inside Ragefire Chasm."] = "Tötet 8 Flammenschlundtroggs und 8 Flammenschlundschamanen im Flammenschlund.",
	["Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."] = "Tötet 8 Gefechtswachen der Klingenhauer, 8 Dornenwirker der Klingenhauer und 8 Kultisten des Totenkopfs und kehrt dann zu Myriam Mondsang nahe dem Eingang zum Hügel der Klingenhauer zurück.",
	["Kill Archmage Arugal and bring his head to Dalar Dawnweaver."] = "Tötet Erzmagier Arugal und bringt seinen Kopf zu Dalar Dämmerweber.",
	["Kill Bazil Thredd in The Stockade and bring his head back to Warden Thelwater."] = "Tötet Bazil Thredd im Verlies und bringt seinen Kopf zu Aufseher Thelwasser zurück.",
	["Kill Bazzalan and Jergosh the Invoker inside Ragefire Chasm."] = "Tötet Bazzalan und Jergosh den Herbeirufer im Flammenschlund.",
	["Kill Dextren Ward in The Stockade and bring his hand to Councilman Millstipe."] = "Tötet Dextren Ward im Verlies und bringt seine Hand zu Ratsherr Millstipe.",
	["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod and Houndmaster Loksey, then report to Raleigh the Devout in Southshore."] = "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandanten Mograine, Herod und Hundemeister Loksey und meldet Euch dann bei Raleigh dem Andächtigen in Süderstade.",
	["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod and Houndmaster Loksey, then report to Varimathras in the Undercity."] = "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandanten Mograine, Herod und Hundemeister Loksey und meldet Euch dann bei Varimathras in Unterstadt.",
	["Kill Kam Deepfury in The Stockade and bring his head to Motley Garmason."] = "Tötet Kam Tiefenzorn im Verlies und bringt seinen Kopf zu Motley Garmason.",
	["Kill Lady Anacondra, Lord Cobrahn, Lord Pythas and Lord Serpentis, then talk to the Disciple of Naralex at the entrance and escort him to Naralex. Protect him during the ritual: Mutanus comes at the end."] = "Tötet Lady Anacondra, Lord Kobrahn, Lord Pythas und Lord Serpentis. Sprecht dann mit dem Jünger von Naralex am Eingang und geleitet ihn zu Naralex. Beschützt ihn während des Rituals: Am Ende erscheint Mutanus.",
	["Kill Mekgineer Thermaplugg and return to High Tinker Mekkatorque."] = "Tötet Robogenieur Thermaplugg und kehrt zu Obertüftler Mekkadrill zurück.",
	["Kill Morphaz and take his blood to Greta Mosshoof in Felwood."] = "Tötet Morphaz und bringt sein Blut zu Greta Moosehuf im Teufelswald.",
	["Kill Princess Theradras."] = "Tötet Prinzessin Theradras.",
	["Kill Rath'mael in Ruins of Lordaeron."] = "Tötet Rath'mael in den Ruinen von Lordaeron.",
	["Kill Shadow Hunter Vosh'gajin and bring her Snakestone to Kilram."] = "Tötet Schattenjägerin Vosh'gajin und bringt ihren Schlangenstein zu Kilram.",
	["Kill Targorr the Dread in The Stockade and bring his head to Guard Berton."] = "Tötet Targorr den Schrecklichen im Verlies und bringt seinen Kopf zu Wache Berton.",
	["Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands."] = "Tötet in den Ausgrabungsstätten einen Schrecken des Hochlands und bringt seinen Wurzelkern zu Rethiel dem Grünwächter im Sumpfland.",
	["Kill the Dark Iron Summoner first: he keeps bringing adds. Then turn on the elemental."] = "Tötet zuerst den Dunkeleisenbeschwörer: Er ruft ständig weitere Gegner herbei. Wendet Euch dann dem Elementar zu.",
	["Kill the green drake Morphaz and bring his tooth to Ogtinc."] = "Tötet den grünen Drachen Morphaz und bringt seinen Zahn zu Ogtinc.",
	["Kill the raptor matriarch in the tall grass. A wave of raptors comes when she dies, and Shadetooth runs in once they are dead."] = "Tötet die Raptormatriarchin im hohen Gras. Bei ihrem Tod kommt eine Welle von Raptoren, und Schattenzahn stürmt herbei, sobald sie tot sind.",
	["Kill the raptor matriarch in the tall grass. Her death brings a wave of raptors, and Shadetooth comes once they are dead: finish the whole wave before he arrives."] = "Tötet die Raptormatriarchin im hohen Gras. Ihr Tod lockt eine Welle von Raptoren an, und Schattenzahn kommt, sobald sie tot sind: Erledigt die ganze Welle, bevor er eintrifft.",
	["Kill the summoner first: he keeps bringing adds. Then turn on the elemental."] = "Tötet zuerst den Beschwörer: Er ruft ständig weitere Gegner herbei. Wendet Euch dann dem Elementar zu.",
