	["Smokey LaRue, Eastern Plaguelands"] = "Smokey LaRue, Östliche Pestländer",
	["Snakestone of the Shadow Huntress"] = "Schlangenstein der Schattenjägerin",
	["Sneed fights from inside the shredder, and climbs out when it is destroyed."] = "Sneed kämpft aus dem Schredder heraus und steigt aus, wenn dieser zerstört wird.",
	["Solution to Doom"] = "Lösung des Verhängnisses",
	["Sometimes found among the Dark Iron agents."] = "Manchmal unter den Agenten der Dunkeleisenzwerge zu finden.",
	["Sometimes found in the bat caves."] = "Manchmal in den Fledermaushöhlen anzutreffen.",
	["Sometimes found in the side passage after Rhahk'Zor."] = "Manchmal im Seitengang hinter Rhahk'Zor zu finden.",
	["Songblade Search"] = "Die Suche nach Songblade",
	["Soulbound Keepsake"] = "Seelengebundenes Andenken",
