	["Sovik, Valley of Honor, Orgrimmar"] = "Sovik, Tal der Ehre, Orgrimmar",
	["Speak to Blastmaster Emi Shortfuse and protect her while she seals the two cave mouths: troggs come in waves, then Grubbis with Chomper."] = "Sprecht mit Sprengmeisterin Emi Kurzlunte und beschützt sie, während sie die beiden Höhleneingänge versiegelt: Troggs kommen in Wellen, dann Grubbis mit Chomper.",
	["Speak to Dorn Plainstalker in Thousand Needles."] = "Sprecht mit Dorn Ebenenpirscher in Tausend Nadeln.",
	["Speak to Je'neu Sancrea in Ashenvale."] = "Sprecht mit Je'neu Sancrea im Eschental.",
	["Speak with Caitlin Grassman in Menethil Harbor."] = "Sprecht mit Caitlin Grassman im Hafen von Menethil.",
	["Speak with Scooty in Booty Bay."] = "Sprecht mit Scooty in Beutebucht.",
	["Speak with Yeh'kinya."] = "Sprecht mit Yeh'kinya.",
	["Spectral Chalice, inside the dungeon"] = "Spektraler Kelch, im Dungeon",
	["Speeds up his or an ally's attacks by 30% for 30 seconds. A priest or a shaman can remove it."] = "Erhöht 30 Sekunden lang sein Angriffstempo oder das eines Verbündeten um 30%. Ein Priester oder Schamane kann ihn entfernen.",
	["Spiders of the courtyard"] = "Spinnen im Hof",
