	["Stage Three: 33% Health"] = "Phase 3: 33% Gesundheit",
	["Stage Two: 66% Health"] = "Phase 2: 66% Gesundheit",
	["Stalker's Thicket"] = "Pirscherdickicht",
	["Starts from Blackhand's Command, a letter dropped in Lower Blackrock Spire."] = "Beginnt mit Schwarzfausts Befehl, einem Brief, der in der Unteren Schwarzfelsspitze erbeutet wird.",
	["Starts from the Blood-Stained Letter."] = "Beginnt mit dem blutbefleckten Brief.",
	["Starving Arcane"] = "Arkaner Hunger",
	["Stay in the room"] = "Bleibt im Raum",
	["Stay on the platform: small adds wait at the room's edge."] = "Bleibt auf der Plattform: Am Rand des Raums warten kleine Adds.",
	["Stay out of her Forked Lightning cone. Frost Nova freezes everyone near her, and she slows a player."] = "Bleibt aus dem Kegel ihres Gabelblitzes heraus. Frostnova friert alle in ihrer Nähe ein, und sie verlangsamt einen Spieler.",
	["Step out of his Flame Spike. A magic dispel removes Flame Shock; interrupt his Shadow Bolt. Fire Nova burns those close to him."] = "Tretet aus seinem Flammenstachel. Flammenschock lässt sich als Magieeffekt bannen; unterbrecht seinen Schattenblitz. Feuernova verbrennt alle in seiner Nähe.",
	["Steps out of his shredder once it breaks."] = "Steigt aus seinem Schredder, sobald dieser zerbricht.",
	["Stomper Kreeg, inside the dungeon"] = "Stampfer Kreeg, im Dungeon",
	["Stone Tablet"] = "Steintafel",
	["Stone tablet inside a vault in the Reliquary of Kings (Durgen Dirgehammer's room)"] = "Steintafel in einem Gewölbe im Reliquiar der Könige (Durgen Klagehammers Raum)",
	["Stormwind"] = "Sturmwind",
	["Stormwind City"] = "Sturmwind",
	["Stormwind Harbor"] = "Hafen von Sturmwind",
	["Stormwind's prison beneath the canals has fallen to a riot. Led by Bazil Thredd of the Defias Brotherhood, the inmates have taken the cell blocks, and the Warden wants the ringleaders dealt with."] = "Sturmwinds Gefängnis unter den Kanälen ist einem Aufstand zum Opfer gefallen. Angeführt von Bazil Thredd von der Defiasbruderschaft haben die Insassen die Zellenblöcke eingenommen, und der Aufseher will, dass mit den Rädelsführern abgerechnet wird.",
	["Strange Water Globe"] = "Seltsame Wasserkugel",
	["Strange Water Globe, dropped by Baron Aquanis inside Blackfathom Deeps"] = "Seltsame Wasserkugel, Beute von Baron Aquanis in der Tiefschwarzen Grotte",
	["Strikes hard at a target down to 20% health or less. Keep the tank above it."] = "Schlägt hart auf ein Ziel mit 20% Gesundheit oder weniger zu. Haltet den Tank darüber.",
	["Stuns a player for 4 seconds."] = "Betäubt einen Spieler 4 Sekunden lang.",
	["Stuns a player for 5 seconds."] = "Betäubt einen Spieler 5 Sekunden lang.",
	["Stuns everyone near him for 4 seconds."] = "Betäubt alle in seiner Nähe 4 Sekunden lang.",
	["Stuns, and calls his guards in when his health runs low."] = "Betäubt und ruft seine Wachen herbei, wenn seine Gesundheit zur Neige geht.",
	["Swamp of Sorrows"] = "Sümpfe des Elends",
	["Tabetha's Task"] = "Tabethas Aufgabe",
	["Tabetha, Dustwallow Marsh"] = "Tabetha, Düstermarschen",
	["Tabitha Heartweaver — The Sepulcher"] = "Tabitha Herzweber — Das Grabmal",
	["Tabitha Heartweaver, Silverpine Forest / The Sepulcher"] = "Tabitha Herzweber, Silberwald / Das Grabmal",
	["Tabitha Heartweaver, The Sepulcher, Silverpine Forest"] = "Tabitha Herzweber, Das Grabmal, Silberwald",
	["Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath."] = "Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort in Kargath zurück.",
	["Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes."] = "Bringt General Drakkisaths Befehl zu Marschall Maxwell in der Brennenden Steppe.",
	["Take a shard of the Felvine once Alzzin the Wildshaper falls, seal it in the Reliquary of Purity and bring it to Rabine Saturna."] = "Nehmt einen Splitter der Teufelsranke, sobald Alzzin der Wildformer gefallen ist, versiegelt ihn im Reliquiar der Reinheit und bringt ihn zu Rabine Saturna.",
	["Take the Arcane Shard from Morphaz and bring it back to Archmage Xylem."] = "Nehmt Morphaz den Arkansplitter ab und bringt ihn zu Erzmagier Xylem zurück.",
	["Take the Azure Key, which Morphaz carries, to Lord Jorach Ravenholdt."] = "Bringt den azurblauen Schlüssel, den Morphaz bei sich trägt, zu Lord Jorach Rabenholdt.",
	["Take the Grimtotem Satchel to Rahauro in Thunder Bluff."] = "Bringt den Ranzen der Grimmtotem zu Rahauro in Donnerfels.",
	["Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands."] = "Bringt den Kopf von Balnazzar zu Herzog Nicholas Zverenhoff in den Östlichen Pestländern.",
	["Take the Healthy Dragon Scale to Betina Bigglezink at Light's Hope Chapel."] = "Bringt die gesunde Drachenschuppe zu Betina Bigglezink an der Kapelle des Hoffnungsvollen Lichts.",
	["Take the Nightmare Shard to Hamuul Runetotem on the Elder Rise."] = "Bringt den Albtraumsplitter zu Hamuul Runentotem auf der Anhöhe der Ältesten.",
	["Take the Nightmare Shard to Mathrengyl Bearwalker in Darnassus."] = "Bringt den Albtraumsplitter zu Mathrengyl Bärenwandler in Darnassus.",
	["Take the Reed-woven Heart back to Caitlin Grassman in Menethil Harbor."] = "Bringt das Schilfgewobene Herz zu Caitlin Grassman im Hafen von Menethil zurück.",
	["Take the Small Scroll to Varimathras in the Undercity."] = "Bringt die Kleine Schriftrolle zu Varimathras in Unterstadt.",
	["Take the Titan Relic to the Elder Rise in Thunder Bluff, to someone who can say more about it."] = "Bringt das Titanenrelikt zur Anhöhe der Ältesten in Donnerfels, zu jemandem, der mehr darüber sagen kann.",
	["Take the bad news back to King Magni Bronzebeard in Ironforge."] = "Überbringt König Magni Bronzebart in Eisenschmiede die schlechte Nachricht.",
	["Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul."] = "Bringt das unvollständige Banner der Provokation zu Falrin Rankenweber in der Bibliothek von Düsterbruch.",
	["Take the letter to the city architect in Stormwind."] = "Bringt den Brief zum Stadtarchitekten in Sturmwind.",
	["Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge."] = "Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga in Eisenschmiede.",
	["Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."] = "Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen in Donnerfels.",
	["Take the reward voucher to Bena Winterhoof in Thunder Bluff."] = "Bringt den Belohnungsgutschein zu Bena Winterhuf in Donnerfels.",
	["Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge."] = "Bringt Euren Belohnungsgutschein zu Dinita Zasterstein im Gewölbe von Eisenschmiede.",
	["Takes control of a player other than his target for 15 seconds (2-second cast). Interrupt it, or dispel it from the player."] = "Übernimmt 15 Sekunden lang die Kontrolle über einen Spieler, der nicht sein Ziel ist (2 Sekunden Zauberzeit). Unterbrecht den Zauber oder bannt den Effekt vom Spieler.",
	["Talendria, Desolace"] = "Talendria, Desolace",
	["Talk to Blastmaster Emi Shortfuse and protect her while she blows up the two cave mouths. Troggs pour out in waves, then Grubbis comes with Chomper."] = "Sprecht mit Sprengmeisterin Emi Kurzlunte und beschützt sie, während sie die beiden Höhleneingänge sprengt. Troggs strömen in Wellen heraus, dann kommt Grubbis mit Chomper.",
	["Talk to Franclorn Forgewright about getting a key to the city."] = "Sprecht mit Franclorn Schmiedewerk über einen Schlüssel zur Stadt.",
	["Talk to Klockmort Spannerspan in Ironforge."] = "Sprecht mit Klockmort Spannersplint in Eisenschmiede.",
	["Talk to Latronicus Moonspear at Feathermoon Stronghold in Feralas."] = "Sprecht mit Latronicus Mondspeer in der Mondfederfeste in Feralas.",
	["Talk to Malyfous Darkhammer in Everlook."] = "Sprecht mit Malyfous Düsterhammer in Ewige Warte.",
	["Talk to Master Mechanic Castpipe in Ironforge."] = "Sprecht mit Mechanikermeister Gussmuff in Eisenschmiede.",
	["Talk to Mayara Brightwing in the Burning Steppes."] = "Sprecht mit Mayara Hellschwinge in der Brennenden Steppe.",
	["Talk to Nara Wildmane nearby in Thunder Bluff."] = "Sprecht mit Nara Wildmähne ganz in der Nähe in Donnerfels.",
	["Talk to Ozzie Togglevolt in Kharanos."] = "Sprecht mit Ozzie Togglevolt in Kharanos.",
	["Talk to Ragnar Thunderbrew in Kharanos."] = "Sprecht mit Ragnar Donnerbräu in Kharanos.",
	["Talk to Shadowmage Vivian Lagrave in Kargath."] = "Sprecht mit Schattenmagierin Vivian Lagrave in Kargath.",
	["Talk to Tabetha in Dustwallow Marsh."] = "Sprecht mit Tabetha in den Düstermarschen.",
	["Talk to Talo Thornhoof at Camp Mojache in Feralas."] = "Sprecht mit Talo Dornhuf im Camp Mojache in Feralas.",
	["Talk to Thrall to take on his mission."] = "Sprecht mit Thrall, um seinen Auftrag anzunehmen.",
	["Talk to Tinkee Steamboil in the Burning Steppes."] = "Sprecht mit Tinkee Kesseldampf in der Brennenden Steppe.",
	["Talk to Tran'rek in Gadgetzan."] = "Sprecht mit Tran'rek in Gadgetzan.",
	["Talk to Yuka Screwspigot in the Burning Steppes."] = "Sprecht mit Yuka Schraubstutz in der Brennenden Steppe.",
	["Talk to the stone watcher, then use the Discs of Norgannon."] = "Sprecht mit dem Steinwächter und benutzt dann die Scheiben von Norgannon.",
