	["Return to Mokvar in Orgrimmar with a set of Beaststalker's Boots, Beaststalker's Pants and Beaststalker's Mantle."] = "Kehrt mit den Stiefeln, der Hose und den Schultern des Sets Eurer Klasse zu Mokvar in Orgrimmar zurück.",
	["Return to Mokvar in Orgrimmar with a set of Magister's Boots, Magister's Leggings and Magister's Mantle."] = "Kehrt mit den Stiefeln, der Hose und den Schultern des Sets Eurer Klasse zu Mokvar in Orgrimmar zurück.",
	["Return to Mokvar in Orgrimmar with a set of Devout Sandals, Devout Skirt and Devout Mantle."] = "Kehrt mit den Stiefeln, der Hose und den Schultern des Sets Eurer Klasse zu Mokvar in Orgrimmar zurück.",
	["Return to Mokvar in Orgrimmar with a set of Shadowcraft Boots, Shadowcraft Pants and Shadowcraft Spaulders."] = "Kehrt mit den Stiefeln, der Hose und den Schultern des Sets Eurer Klasse zu Mokvar in Orgrimmar zurück.",
	["Return to Mokvar in Orgrimmar with a set of Dreadmist Sandals, Dreadmist Leggings and Dreadmist Mantle."] = "Kehrt mit den Stiefeln, der Hose und den Schultern des Sets Eurer Klasse zu Mokvar in Orgrimmar zurück.",
