	["Talk to Furen Longbeard in Stormwind to get your armour."] = "Sprecht mit Furen Langbart in Sturmwind, um Eure Rüstung zu erhalten.",
	["Talk to Thun'grim Firegaze in the Barrens to get your armour."] = "Sprecht mit Thun'grim Brandblick im Brachland, um Eure Rüstung zu erhalten.",
	["Kill 12 Mana Surges in the allowed time limit."] = "Tötet 12 Manawogen in der vorgegebenen Zeit.",
	["Talk to Tabetha in Dustwallow Marsh for your reward."] = "Sprecht mit Tabetha in den Düstermarschen, um Eure Belohnung zu erhalten.",
	["Bring a Kor Gem to Thundris Windweaver in Darkshore."] = "Bringt einen Kor-Edelstein zu Thundris Windwirker an der Dunkelküste.",
	["Speak with Wizzle Brassbolts in the Shimmering Flats."] = "Sprecht mit Wizzel Kupferbolz in der Schimmernden Ebene.",
	["Travel to Gershala Nightwhisper in Auberdine."] = "Reist zu Gershala Nachtraunen in Auberdine.",
	["Speak with Shoni the Shilent in Stormwind."] = "Sprecht mit Shoni der Shtillen in Sturmwind.",
	["Speak with Deliana at The High Seat in Ironforge."] = "Sprecht mit Deliana am Hohen Sitz in Eisenschmiede.",
	["Speak with Mokvar at Grommash Hold in Orgrimmar's Valley of Wisdom."] = "Sprecht mit Mokvar in der Feste Grommash im Tal der Weisheit von Orgrimmar.",
	["Give Deliana your Wildheart Cowl and Wildheart Vest."] = "Gebt Deliana den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Deliana your Beaststalker's Cap and Beaststalker's Tunic."] = "Gebt Deliana den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Deliana your Magister's Crown and Magister's Robes."] = "Gebt Deliana den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Deliana your Lightforge Helm and Lightforge Breastplate."] = "Gebt Deliana den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Deliana your Devout Crown and Devout Robe."] = "Gebt Deliana den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Deliana your Shadowcraft Cap and Shadowcraft Tunic."] = "Gebt Deliana den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Deliana your Dreadmist Mask and Dreadmist Robe."] = "Gebt Deliana den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Deliana your Helm of Valor and Breastplate of Valor."] = "Gebt Deliana den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Mokvar your Wildheart Cowl and Wildheart Vest."] = "Gebt Mokvar den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Mokvar your Beaststalker's Cap and Beaststalker's Tunic."] = "Gebt Mokvar den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Mokvar your Magister's Crown and Magister's Robes."] = "Gebt Mokvar den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Mokvar your Devout Crown and Devout Robe."] = "Gebt Mokvar den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Mokvar your Shadowcraft Cap and Shadowcraft Tunic."] = "Gebt Mokvar den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Mokvar your Dreadmist Mask and Dreadmist Robe."] = "Gebt Mokvar den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Mokvar your Helm of Valor and Breastplate of Valor."] = "Gebt Mokvar den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Give Mokvar your Coif of Elements and Vest of Elements."] = "Gebt Mokvar den Helm und die Brustrüstung des Sets Eurer Klasse.",
	["Thundris Windweaver, Auberdine, Darkshore"] = "Thundris Windwirker, Auberdine, Dunkelküste",
	["Argos Nightwhisper, Stormwind City"] = "Argos Nachtraunen, Sturmwind",
	["Thundris Windweaver"] = "Thundris Windwirker",
