	["Wizzle Brassbolts"] = "Wizzel Kupferbolz",
	["Argos Nightwhisper"] = "Argos Nachtraunen",
	["Shoni the Shilent"] = "Shoni die Shtille",
	["The Mana Surges come out of a rift Tabetha opens by her house. You have 10 minutes."] = "Die Manawogen kommen aus einem Riss, den Tabetha bei ihrem Haus öffnet. Ihr habt 10 Minuten.",
	["Optional: it leads to Gahz'rilla."] = "Optional: Sie führt zu „Gahz'rilla“.",
	["Optional: it leads to Researching the Corruption."] = "Optional: Sie führt zu „Erforschung der Verderbnis“.",
	["Optional: it leads to Underground Assault."] = "Optional: Sie führt zu „Unterirdischer Angriff“.",
	["General Drakkisath drops the chest here. Darkmaster Gandling in Scholomance drops the helm."] = "General Drakkisath lässt hier die Brustrüstung fallen. Den Helm lässt Dunkelmeister Gandling in der Scholomance fallen.",
	["Darkmaster Gandling drops the helm here. General Drakkisath in Upper Blackrock Spire drops the chest."] = "Dunkelmeister Gandling lässt hier den Helm fallen. Die Brustrüstung lässt General Drakkisath in der Oberen Schwarzfelsspitze fallen.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: the Corrupted Kor Gem, from the Blackfathom Sea Witches inside or the Tide Priestesses and Oracles at the entrance in Ashenvale. The rest: Whitestone Oak Lumber in the Deadmines, Jordan's Smithing Hammer in Shadowfang Keep and Jordan's ore shipment in Loch Modan."] = "Eine Paladinquest für Menschen und Zwerge mit Teilen aus mehreren Orten. Hier: der Verderbte Kor-Edelstein, von den Meerhexen der Tiefschwarzen Grotte im Inneren oder von den Gezeitenpriesterinnen und Orakeln am Eingang im Eschental. Der Rest: Weißsteineichenholz in den Todesminen, Jordans Schmiedehammer in Burg Schattenfang und Jordans Erzlieferung in Loch Modan.",
	-- Notes that name where a chain goes next, on another page or outside (the owner's calls of 2026-11-03 on which quests and chains belong) (2026-11-03; drafted, to be checked)
	["Leads into a chain that carries on with Bazil Thredd and on to The Stockade Riots in the Stockade."] = "Führt zu einer Questreihe, die mit Bazil Thredd weitergeht und bis zu „Aufruhr im Verlies“ im Verlies führt.",
	["Then Master Apothecary Faranell gives Hearts of Zeal, done in the Scarlet Monastery."] = "Danach gibt Apothekermeister Faranell „Herzen des Eifers“, zu erledigen im Scharlachroten Kloster.",
	["Then Theldurin the Lost gives To Ironforge for Yagyin's Digest (Alliance) or To the Undercity for Yagyin's Digest (Horde), a short chain outside."] = "Danach gibt Theldurin der Verlorene „Nach Eisenschmiede für Yagyins Auszug“ (Allianz) oder „Nach Unterstadt für Yagyins Auszug“ (Horde), eine kurze Questreihe außerhalb.",
	["Then High Explorer Magellas gives Portents of Uldum, which goes on to the gates of Uldum in Tanaris."] = "Danach gibt Hochforscher Magellas „Vorzeichen von Uldum“. Die Questreihe führt weiter zu den Toren von Uldum in Tanaris.",
	["Then Sage Truthseeker gives Portents of Uldum, which goes on to the gates of Uldum in Tanaris."] = "Danach gibt der Weise Wahrheitssucher „Vorzeichen von Uldum“. Die Questreihe führt weiter zu den Toren von Uldum in Tanaris.",
	["For alchemists (skill 210), Ghak Healtouch then gives Badlands Reagent Run II, done in the Badlands."] = "Für Alchemisten (Fertigkeit 210) gibt Ghak Heilhand danach „Reagenzien aus dem Ödland II“, zu erledigen im Ödland.",
	["Then Yeh'kinya gives The Ancient Egg, which leads to The God Hakkar in the Sunken Temple."] = "Danach gibt Yeh'kinya „Das uralte Ei“. Diese Quest führt zu „Der Gott Hakkar“ im Versunkenen Tempel.",
	["Then Thadius Grimshade gives The Divination, a chain that ends with Saving Sharpbeak in the Hinterlands."] = "Danach gibt Thadius Grimmschatten „Die Weissagung“, eine Questreihe, die mit „Rettet Scharfschnabel“ im Hinterland endet.",
	["Then Master Gadrin gives Summoning Shadra, done at Shadra'Alor in the Hinterlands."] = "Danach gibt Meister Gadrin „Shadra beschwören“, zu erledigen in Shadra'Alor im Hinterland.",
	["Then Warlord Goretooth gives Eitrigg's Wisdom, which takes you to Orgrimmar. The chain goes on to For The Horde! in Upper Blackrock Spire, then to the Onyxia attunement."] = "Danach gibt Kriegsherr Bluthauer „Eitriggs Weisheit“. Die Quest schickt Euch nach Orgrimmar. Die Questreihe führt weiter zu „Für die Horde!“ in der Oberen Schwarzfelsspitze und dann zur Abstimmung auf Onyxia.",
	["Then Marshal Maxwell gives General Drakkisath's Demise, done in Upper Blackrock Spire."] = "Danach gibt Marschall Maxwell „General Drakkisaths Untergang“, zu erledigen in der Oberen Schwarzfelsspitze.",
	["Then Bodley gives Mea Culpa, Lord Valthalak, done in Upper Blackrock Spire."] = "Danach gibt Bodley „Mea Culpa, Lord Valthalak“, zu erledigen in der Oberen Schwarzfelsspitze.",
	["Then Haleh, in Winterspring, gives Wrath of the Blue Flight. The chain goes on to Jeziba in Andorhal, whose Catalogue of the Wayward offers Breastplate of the Chromatic Flight and Legplates of the Chromatic Defier. Each needs Gyth's Chromatic Carapace and 10 Brilliant Chromatic Scales from Upper Blackrock Spire."] = "Danach gibt Haleh in Winterquell „Der Zorn des blauen Drachenschwarms“. Die Questreihe führt weiter zu Jeziba in Andorhal; dort bietet das Verzeichnis der Abtrünnigen „Brustplatte des chromatischen Schwarms“ und „Beinplatten des chromatischen Trotzers“ an. Jede verlangt Gyths chromatischen Panzer und 10 glänzende chromatische Schuppen aus der Oberen Schwarzfelsspitze.",
	["Then Duke Hydraxis gives The Molten Core, done in Molten Core."] = "Danach gibt Fürst Hydraxis „Der Geschmolzene Kern“, zu erledigen im Geschmolzenen Kern.",
	["Then Falrin Treeshaper gives The Challenge, done at the Ring of Law in Blackrock Depths."] = "Danach gibt Falrin Rankenweber „Die Herausforderung“, zu erledigen im Ring des Gesetzes in den Schwarzfelstiefen.",
	["Then Lord Grayson Shadowbreaker gives The Divination Scryer. The chain ends with Judgment and Redemption in Scholomance."] = "Danach gibt Lord Grayson Schattenbruch „Das Orakel der Anrufung“. Die Questreihe endet mit „Gerechtigkeit und Erlösung“ in der Scholomance.",
	["Then Anthion Harmon gives Anthion's Strange Request. The chain goes on to Anthion's Old Friend in Dire Maul."] = "Danach gibt Anthion Harmon „Anthions merkwürdige Anforderung“. Die Questreihe führt weiter zu „Anthions alter Freund“ in Düsterbruch.",
	["Then Duke Nicholas Zverenhoff gives Above and Beyond, done at the Service Gate."] = "Danach gibt Herzog Nicholas Zverenhoff „Über die Pflicht hinaus“, zu erledigen am Dienstboteneingang.",
	["Optional: it leads to Blackfathom Villainy."] = "Optional: Sie führt zu „Schurkerei in der Tiefschwarzen Grotte“.",
	-- City of Dalaran: the Horde's Heart of Disruption names who starts the chain, as the Image of Archmage Modera gives the quest itself (2026-11-03; drafted, to be checked)
	["Magus Wordeen Voidglare in Tarren Mill starts the chain with Prison Break In and Key to the City. At the Lordamere Internment Camp, kill four traitors for their artifacts (they take 5 to 10 minutes to come back) and take the Grimy Key from the Warden's Footlocker, upstairs in the two-storey building. Blood in the Streets then leads through the north sewers to the Image of Archmage Modera. It gives the Dalaran Sewer Key, and Shrewd Negotiations follows, to Archmage Celindra. The mote drops from the Shade of the Archmage, the last boss."] = "Magus Wordeen Voidglare in Tarrens Mühle beginnt die Questreihe mit „Einbruch ins Gefängnis“ und „Der Schlüssel zur Stadt“. Tötet im Internierungslager von Lordamere vier Verräter für ihre Artefakte (sie erscheinen erst nach 5 bis 10 Minuten wieder) und nehmt den Schmutzigen Schlüssel aus der Truhe des Aufsehers im Obergeschoss des zweistöckigen Gebäudes. Danach führt „Blut in den Straßen“ durch die nördliche Kanalisation zum Abbild der Erzmagierin Modera. Dort erhaltet Ihr den Schlüssel zur Kanalisation von Dalaran, und es folgt „Geschickte Verhandlungen“ zu Erzmagierin Celindra. Das Partikel lässt der Schemen des Erzmagiers fallen, der letzte Boss.",
	-- The Deadmines, Shadowfang Keep, Blackfathom Deeps and Gnomeregan (the deep audit's plan step 5): A Moon-Kissed Blade's Kor Gem and what follows it, Seeking the Kor Gem's link back, the Deadmines' chains before you go, The Orb of Soran'ruk's note, the lead-in notes, Rig Wars' level and the Sparklematic machines (2026-11-03; drafted, to be checked)
	["Bring Trevan Rol in the Sepulcher the Whitestone Oak Lumber, the Enchanted Silver Ingot and the Purified Kor Gem he needs."] = "Bringt Trevan Rol im Grabmal das Weißsteineichenholz, den verzauberten Silberbarren und den Gereinigten Kor-Edelstein, die er braucht.",
	["A paladin quest for the Forsaken. Here: Whitestone Oak Lumber, which the Goblin Woodcarvers drop. The Purified Kor Gem comes from Seeking the Kor Gem, from Ulric Frostveil at Zoram'gar Outpost; its Corrupted Kor Gem drops in Blackfathom Deeps. Trevan then sends you to Ott, the weaponsmith in Tarren Mill (Hillsbrad Foothills), who forges the Moonsilver Blade. Lumina Windsinger then has you use it on Old Fire-Eye in southern Silverpine, for Wolfsbane."] = "Eine Paladinquest für die Verlassenen. Hier: Weißsteineichenholz, das die Goblinholzschnitzer fallen lassen. Den Gereinigten Kor-Edelstein gibt es bei „Auf der Suche nach dem Kor-Edelstein“ von Ulric Frostveil im Außenposten von Zoram'gar; den Verderbten Kor-Edelstein dafür findet Ihr in der Tiefschwarzen Grotte. Danach schickt Euch Trevan zu Ott, dem Waffenschmied in Tarrens Mühle (Vorgebirge des Hügellands), der die Mondsilberklinge schmiedet. Lumina Windsänger lässt Euch sie dann gegen Alt-Feuerauge im Süden des Silberwalds einsetzen, für Wolfsbann.",
	["A paladin quest for the Horde. The Corrupted Kor Gem drops from the Blackfathom Sea Witches inside, or the Tide Priestesses and Oracles at the entrance. The Purified Kor Gem it gives is for A Moon-Kissed Blade, which Trevan Rol in the Sepulcher takes with lumber from the Deadmines."] = "Eine Paladinquest für die Horde. Den Verderbten Kor-Edelstein lassen die Meerhexen der Tiefschwarzen Grotte im Inneren fallen, oder die Gezeitenpriesterinnen und Orakel am Eingang. Der Gereinigte Kor-Edelstein, den sie gibt, ist für „Eine mondgeküsste Klinge“, die Trevan Rol im Grabmal zusammen mit Holz aus den Todesminen annimmt.",
	["The Defias Brotherhood chain"] = "Die Questreihe der Defiasbruderschaft",
	["Alba Fairmoon's chain"] = "Alba Fairmoons Questreihe",
	["Alba Fairmoon at Sentinel Hill gives Destruction in Deadmines at the end of a chain of quests in Westfall and Stormwind. On the way, Sprite Jumpsprocket in the Dwarven District of Stormwind asks for 10 Coarse Dynamite: make it, trade for it or buy it at the auction house."] = "Alba Fairmoon auf der Späherkuppe vergibt „Zerstörung in den Todesminen“ am Ende einer Questreihe in Westfall und Sturmwind. Unterwegs verlangt Sprite Jumpsprocket im Zwergendistrikt von Sturmwind 10 Grobes Dynamit: Stellt es her, tauscht es ein oder kauft es im Auktionshaus.",
	["A warlock quest. Here: the Large Soran'ruk Fragment, from Shadowfang Darksouls. The 3 small ones drop from Twilight Acolytes in Blackfathom Deeps."] = "Eine Hexenmeisterquest. Hier: das Große Fragment von Soran'ruk, von den Dunkelseelen der Schattenfänge. Die 3 kleinen lassen die Akolythen des Schattenhammers in der Tiefschwarzen Grotte fallen.",
	["Sovik in Orgrimmar sends you to Scooty in Booty Bay. Take Rig Wars from Nogg first (from level 25); you need not finish it. Scooty's Gnomer-gooooone! gives the {item:9173:Goblin Transponder:1}. In the quest's own words, it lets you step on Scooty's pad in Booty Bay to go to Gnomeregan, and the pad there brings you back. This is not yet checked on Forever."] = "Sovik in Orgrimmar schickt Euch zu Scooty in Beutebucht. Nehmt zuerst „Maschinenkriege“ bei Nogg an (ab Stufe 25); abschließen müsst Ihr sie nicht. Scootys Quest „Gnomer-weeeeg!“ bringt den {item:9173:Goblin Transponder:1} ein. Laut der Quest selbst tretet Ihr damit auf Scootys Plattform in Beutebucht, um nach Gnomeregan zu gelangen, und die Plattform dort bringt Euch zurück. Auf Forever ist das noch nicht geprüft.",
	["There are three Sparklematic 5200 machines, and each gives its own version of this quest. Once you do it at one, the other two close."] = "Es gibt drei Funkelmat-5200-Maschinen, und jede vergibt ihre eigene Version dieser Quest. Sobald Ihr sie an einer erledigt, schließen sich die anderen beiden.",
	["Repeatable. Each go costs 3 silver. There are three Sparklematic 5200 machines, and each gives its own version of this quest. Once you do it at one, the other two close."] = "Wiederholbar. Jeder Durchgang kostet 3 Silber. Es gibt drei Funkelmat-5200-Maschinen, und jede vergibt ihre eigene Version dieser Quest. Sobald Ihr sie an einer erledigt, schließen sich die anderen beiden.",
	-- The quest review of 2026-11-03: where a chain goes next split off its note (shown on the quest's own page alone), every lead-in row marked optional and the quests it leads to no longer naming it, Seeking the Kor Gem given only while The Test of Righteousness is in the log, the Deadmines' Defias Brotherhood chain before you go, and More Sparklematic Action's note (2026-11-03; drafted, to be checked)
	["Then Bodley gives Components of Importance. The amulet's quests go on in Blackrock Spire, Dire Maul, Scholomance and Stratholme."] = "Danach gibt Bodley „Wichtige Bestandteile“. Die Quests des Amuletts gehen in der Schwarzfelsspitze, in Düsterbruch, in der Scholomance und in Stratholme weiter.",
	["Then Bodley gives Final Preparations, which goes on in Blackrock Spire."] = "Danach gibt Bodley „Letzte Vorbereitungen“. Die Questreihe geht in der Schwarzfelsspitze weiter.",
	["A step of the paladin's charger quests. The Stratholme Holy Water comes from supply crates inside Stratholme."] = "Ein Schritt der Streitross-Questreihe der Paladine. Das Weihwasser von Stratholme kommt aus Vorratskisten in Stratholme.",
	["Then Lord Grayson Shadowbreaker gives Ancient Equine Spirit, done in Dire Maul's Capital Gardens."] = "Danach gibt Lord Grayson Schattenbruch „Der uralte Pferdegeist“, zu erledigen in den Hauptstadtgärten von Düsterbruch.",
	["A step of the warlock's Dreadsteed quests."] = "Ein Schritt der Schreckensross-Questreihe der Hexenmeister.",
	["With Arcanite, it leads to Dreadsteed of Xoroth, done in Dire Maul's Capital Gardens."] = "Zusammen mit „Arkanit“ führt sie zu „Schreckensross von Xoroth“, zu erledigen in den Hauptstadtgärten von Düsterbruch.",
	["For alchemists (skill 210), Jarkal Mossmeld then gives Badlands Reagent Run II, done in the Badlands."] = "Für Alchemisten (Fertigkeit 210) gibt Jarkal Mossmeld danach „Reagenzien aus dem Ödland II“, zu erledigen im Ödland.",
	["Part of the chain The Unsent Letter starts, from Edwin VanCleef in the Deadmines."] = "Teil der Questreihe, die mit „Der nicht abgeschickte Brief“ von Edwin VanCleef in den Todesminen beginnt.",
	["Warden Thelwater then gives The Curious Visitor, which goes on in Stormwind."] = "Danach gibt Aufseher Thelwasser „Der neugierige Besucher“. Die Questreihe geht in Sturmwind weiter.",
	["Techbot stands outside the instance, in Dun Morogh."] = "Techbot steht außerhalb der Instanz, in Dun Morogh.",
	["A White Punch Card drops from mobs outside the instance; run it through Matrix Punchograph 3005-A (Train Depot, outside), 3005-B (the Dormitory), 3005-C (Electrocutioner 6000's platform) and 3005-D (lower Engineering Labs) to get the Prismatic Punch Card."] = "Eine Weiße Lochkarte erbeutet Ihr von Gegnern vor der Instanz. Steckt sie nacheinander in den Matrix-Prägograph 3005-A (Bahndepot, draußen), 3005-B (Der Schlafsaal), 3005-C (die Plattform von Elektrokutor 6000) und 3005-D (untere Ingenieurslabore), um die Prismalochkarte zu erhalten.",
	["Optional: it leads to Hurley Blackbreath."] = "Optional: Sie führt zu „Hurley Schwarzatem“.",
	["Optional: it leads to Ribbly Screwspigot."] = "Optional: Sie führt zu „Ribbly Schraubstutz“.",
	["Optional: it leads to Lost Thunderbrew Recipe."] = "Optional: Sie führt zu „Verlorenes Donnerbräurezept“.",
	["Optional: it leads to Doomrigger's Clasp."] = "Optional: Sie führt zu „Doomriggers Spange“.",
	["Optional: it leads to The Darkstone Tablet."] = "Optional: Sie führt zu „Die Dunkelsteintafel“.",
	["Optional: it leads to Egg Freezing."] = "Optional: Sie führt zu „Eier einfrieren“.",
	["Optional: it leads to Save Techbot's Brain!"] = "Optional: Sie führt zu „Rettet Techbots Gehirn!“.",
	["Optional: it leads to Essential Artificials."] = "Optional: Sie führt zu „Essenzielle Kunstteile“.",
	["Optional: it leads to Gnogaine."] = "Optional: Sie führt zu „Gnogaine“.",
	["Optional: it leads to Data Rescue."] = "Optional: Sie führt zu „Datenrettung“.",
	["Optional: it leads to Lost in the Thicket Things."] = "Optional: Sie führt zu „Verloren im Dickicht“.",
	["Optional: it leads to The Essence of Aku'Mai."] = "Optional: Sie führt zu „Die Essenz von Aku'Mai“.",
	["Optional: it leads to Lethtendris's Web. Also from Courier Hammerfall in Ironforge and Herald Moonstalker in Darnassus."] = "Optional: Sie führt zu „Lethtendris' Netz“. Auch bei Kurier Hammerfall in Eisenschmiede und Herold Mondpirscher in Darnassus erhältlich.",
	["Optional: it leads to Lethtendris's Web. Also from Harbinger Balthazad in Undercity and Bluff Runner Windstrider in Thunder Bluff."] = "Optional: Sie führt zu „Lethtendris' Netz“. Auch bei Künder Balthazad in Unterstadt und Kliffläufer Windschreiter in Donnerfels erhältlich.",
	["Repeatable. Thundris gives it only while The Test of Righteousness is in your quest log. The Corrupted Kor Gem drops from the Blackfathom Sea Witches inside, or the Tide Priestesses and Oracles at the entrance."] = "Wiederholbar. Thundris gibt sie nur, solange „Die Prüfung der Rechtschaffenheit“ in Eurem Questlog ist. Den Verderbten Kor-Edelstein lassen die Meerhexen der Tiefschwarzen Grotte im Inneren fallen, oder die Gezeitenpriesterinnen und Orakel am Eingang.",
	["Gryan Stoutmantle at Sentinel Hill in Westfall starts The Defias Brotherhood. Its first steps take you to Lakeshire and Stormwind and back, then send you after a Defias Messenger in Westfall. Then you escort the Defias Traitor to the Brotherhood's hideout. After that, Gryan gives the step done here, and Scout Riell gives Red Silk Bandanas."] = "Gryan Starkmantel auf der Späherkuppe in Westfall beginnt „Die Defiasbruderschaft“. Die ersten Schritte führen Euch nach Seenhain und Sturmwind und zurück, dann auf die Spur eines Defiasboten in Westfall. Danach geleitet Ihr den Defiasverräter zum Versteck der Bruderschaft. Erst dann gibt Gryan den Schritt, der hier erledigt wird, und Späherin Riell „Rote Seidenkopftücher“.",
	-- Razorfen Kraul: Speak with Thun'grim, Brutal Armor's lead-in, as a row marked optional as every other lead-in is: its name, objective, giver, giver's map label and note (Brutal Armor's shorter note already has its key, shared with Fire Hardened Mail) (2026-11-04; drafted, to be checked)
	["Speak with Thun'grim"] = "Sprecht mit Thun'grim",
	["Speak with Thun'grim Firegaze in the Barrens."] = "Sprecht mit Thun'grim Brandblick im Brachland.",
	["Ruga Ragetotem, Camp Taurajo, The Barrens"] = "Ruga Zorntotem, Camp Taurajo, Brachland",
	["Ruga Ragetotem"] = "Ruga Zorntotem",
	["Optional: it leads to Brutal Armor."] = "Optional: Sie führt zu „Brutale Rüstung“.",
	-- The steps the Quests tab now opens as parts of a row of same-named quests (Hidden Enemies, The Defias Brotherhood, The Test of Righteousness, Test of Lore, A Sign of Hope, The Rise of the Machines, Of Love and Family, The Restless Souls, Explosive Consultation): their objectives (2026-11-04; drafted, to be checked)
	["Gryan Stoutmantle wants you to talk to Wiley in Lakeshire."] = "Gryan Starkmantel möchte, dass Ihr mit Wiley in Seenhain sprecht.",
	["Take Wiley's Note to Gryan Stoutmantle in Westfall."] = "Bringt Wileys Notiz zu Gryan Starkmantel in Westfall.",
	["Take Wiley's Note to Mathias Shaw in Stormwind."] = "Bringt Wileys Notiz zu Mathias Shaw in Sturmwind.",
	["Take Shaw's report to Gryan Stoutmantle in Westfall."] = "Bringt Shaws Bericht zu Gryan Starkmantel in Westfall.",
	["Track down the Defias Messenger in Westfall and bring his message to Stoutmantle."] = "Spürt den Defiasboten in Westfall auf und bringt seine Nachricht zu Starkmantel.",
	["Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information."] = "Geleitet den Defiasverräter zum geheimen Versteck der Defiasbruderschaft. Sobald er Euch gezeigt hat, wo sich VanCleef und seine Männer verstecken, kehrt mit dieser Information zu Gryan Starkmantel zurück.",
	["Find Prospector Ryedol and let him know Hammertoe Grez is alive."] = "Findet Prospektor Ryedol und lasst ihn wissen, dass Hammerzeh Grez lebt.",
	["Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."] = "Findet Braug Trübgeist nahe dem Eingang zum Talondeep-Pfad im Steinkrallengebirge.",
	["Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."] = "Findet das Vermächtnis der Aspekte und bringt es zu Braug Trübgeist nahe dem Eingang zum Talondeep-Pfad im Steinkrallengebirge.",
	["Find Parqual Fintallas in Undercity."] = "Findet Parqual Fintallas in Unterstadt.",
	["Speak to Jordan Stilwell in Ironforge"] = "Sprecht mit Jordan Stilwell in Eisenschmiede",
	["Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania. You recall Theodora mentioning the golems and elementals of that region as being a source for these shards."] = "Reist in die Brennende Steppe und beschafft 10 zersplitterte Elementarsplitter für Hierophantin Theodora Mulvadania. Ihr erinnert Euch, dass Theodora die Golems und Elementare dieser Gegend als Quelle dieser Splitter nannte.",
	["Take the Elemental Shard Sample to Lotwil Veriatus. You recall Theodora saying that Lotwil was stationed in a camp to the east."] = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus. Ihr erinnert Euch, dass Theodora sagte, Lotwil habe sein Lager weiter östlich aufgeschlagen.",
	["Find Egan. You only know that he was last seen around Stratholme."] = "Findet Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde.",
	["Bring a Lieutenant's Insignia to Thrall in Orgrimmar."] = "Bringt ein Leutnantsabzeichen zu Thrall in Orgrimmar.",
	["Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar."] = "Bringt das Leutnantsabzeichen zu Neeru Feuerklinge und sprecht mit ihm. Findet heraus, ob er Euch für ein Mitglied der Brennenden Klinge hält, und kehrt dann zu Thrall in Orgrimmar zurück.",
	["Speak to Neeru Fireblade in Orgrimmar."] = "Sprecht mit Neeru Feuerklinge in Orgrimmar.",
	["Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."] = "Reist zur Insel Caer Darrow im südlichen Zentrum der Pestländer und sucht nach Hinweisen darauf, wo sich das Gemälde befindet.",
	["Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready."] = "Beantwortet die Frage von Braug Trübgeist richtig und sprecht dann erneut mit ihm. Er bleibt im Steinkrallengebirge, bis Ihr bereit seid.",
	["Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready."] = "Beantwortet die Frage von Parqual Fintallas richtig und sprecht dann erneut mit ihm. Er bleibt in Unterstadt, bis Ihr bereit seid.",
	["Travel to the Dwarven District in Stormwind and find an engineer who can help."] = "Reist zum Zwergendistrikt in Sturmwind und findet einen Ingenieur, der helfen kann.",
	["Return to Alba Fairmoon in Westfall."] = "Kehrt zu Alba Fairmoon in Westfall zurück.",
	-- The steps the Quests tab now lists one by one in a chain, numbered as parts of a name (The Tome of Valor, The True Masters, Down the Scarlet Path, Prospect of Faith, Passing Word of a Threat, The Smoldering Ruins of Thaurissan, Detonation at a Distance): their objectives and givers (2026-11-06; drafted, to be checked)
	["Talk to someone in Stormwind Intelligence about acquiring a remote detonator."] = "Sprecht mit jemandem beim Geheimdienst von Sturmwind darüber, wie Ihr an einen Fernzünder kommt.",
	["Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind."] = "Bringt den Fernzünderbausatz zu Sprite Jumpsprocket im Zwergendistrikt von Sturmwind.",
	["Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point."] = "Vernichtet 30 untote Verwüster und kehrt dann zu Bruder Anton an der Nijelspitze zurück.",
	["Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore."] = "Bringt Bruder Antons Empfehlungsschreiben zu Raleigh dem Andächtigen in Süderstade.",
	["Take Hammertoe's Amulet to Prospector Ryedol in the Badlands."] = "Bringt Hammerzehs Amulett zu Prospektor Ryedol im Ödland.",
	["Take Hammertoe's Amulet to Historian Karnik in Ironforge."] = "Bringt Hammerzehs Amulett zu Historiker Karnik in Eisenschmiede.",
	["Find Advisor Belgrum and give him his note."] = "Findet Berater Belgrum und gebt ihm seine Notiz.",
	["Speak to Historian Karnik."] = "Sprecht mit Historiker Karnik.",
	["Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."] = "Reist nach Seenhain und überbringt Friedensrichter Solomon den Brief von Helendis Flusshorn.",
	["Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon. Bolvar resides in Stormwind Keep."] = "Reist nach Sturmwind und überbringt Hochlord Bolvar Fordragon Solomons Bittschrift. Bolvar hält sich in Burg Sturmwind auf.",
	["Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor."] = "Sprecht mit Hochlord Bolvar Fordragon, nachdem Ihr mit Lady Katrana Prestor gesprochen habt.",
	["Take Bolvar's Decree to Magistrate Solomon in Lakeshire."] = "Bringt Bolvars Erlass zu Friedensrichter Solomon in Seenhain.",
	["Speak with Marshal Maxwell in the Burning Steppes."] = "Sprecht mit Marschall Maxwell in der Brennenden Steppe.",
	["Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task. You recall Marshal Maxwell telling you to search for him in a cave to the north."] = "Sprecht mit dem Zerlumpten John, um zu erfahren, was mit Marschall Windsor geschehen ist, und kehrt danach zu Marschall Maxwell zurück. Ihr erinnert Euch, dass Marschall Maxwell sagte, Ihr solltet in einer Höhle im Norden nach ihm suchen.",
	["Listen to Royal Historian Archesonus recant the history of Thaurissan."] = "Hört Euch an, wie der Königliche Historiker Archesonus die Geschichte von Thaurissan erzählt.",
	["Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."] = "Reist zu den Ruinen von Thaurissan in der Brennenden Steppe und sammelt an den Relikten von Thaurissan Informationen. Kehrt mit den Informationen zum Königlichen Historiker Archesonus zurück.",
	["Speak to Duthorian Rall in Stormwind."] = "Sprecht mit Duthorian Rall in Sturmwind.",
	["Find Daphne Stilwell in Westfall."] = "Findet Daphne Stilwell in Westfall.",
	["Defend Daphne Stilwell from the Defias attack. Neither of your spirits must be released from their mortal coils if you wish to succeed. After you are successful, speak to Daphne Stilwell again."] = "Verteidigt Daphne Stilwell gegen den Angriff der Defias. Keiner von Euch beiden darf dabei sterben, wenn Ihr Erfolg haben wollt. Sprecht danach erneut mit Daphne Stilwell.",
	["Sprite Jumpsprocket, Stormwind City"] = "Sprite Jumpsprocket, Sturmwind",
	["Jasper Fel, Stormwind City"] = "Jasper Fel, Sturmwind",
	["Brother Anton, Desolace"] = "Bruder Anton, Desolace",
	["Raleigh the Devout, Hillsbrad Foothills"] = "Raleigh der Andächtige, Vorgebirge des Hügellands",
	["Historian Karnik, Ironforge"] = "Historiker Karnik, Eisenschmiede",
	["Advisor Belgrum, Ironforge"] = "Berater Belgrum, Eisenschmiede",
	["Magistrate Solomon, Redridge Mountains"] = "Friedensrichter Solomon, Rotkammgebirge",
	["Royal Historian Archesonus, Ironforge"] = "Königlicher Historiker Archesonus, Eisenschmiede",
	["Duthorian Rall, Stormwind City"] = "Duthorian Rall, Sturmwind",
	["Daphne Stilwell, Westfall"] = "Daphne Stilwell, Westfall",
	-- Ruins of Lordaeron: Unending Torment's objectives (parts 2, 4 and 5), and where Remember That I Love You
	-- goes next (2026-11-10; drafted, to be checked)
	["Bring the Head of the Baron to Othmar's body, the Unfinished Abomination, in the Undercity."] = "Bringt den Kopf des Barons zu Othmars Leib, der Unvollendeten Monstrosität, in Unterstadt.",
	["Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the herbalism trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter, for Master Apothecary Faranell."] = "Beschafft für Apothekermeister Faranell eine Giftige Schädelkappe von Tawny Grisette im Handelsviertel, Blasenkraut beim Kräuterkundelehrer und Essenz der Pein vom Giftverkäufer im Schurkenviertel.",
	["Inject the Hissing Serum into the system above Othmar's body, then report to Master Apothecary Faranell."] = "Spritzt das Zischende Serum in die Apparatur über Othmars Leib und meldet Euch dann bei Apothekermeister Faranell.",
	["Then Orphan Matron Nightingale gives Remember That I Love You: take the Blood-Stained Letter to Avette Fellwood in Duskwood."] = "Danach gibt Waisenmatrone Nachtigall „Vergiss nicht, dass ich dich liebe“: Bringt den blutbefleckten Brief zu Avette Fellwood im Dämmerwald.",
	-- The quest check of 2026-11-05 (the owner's calls of that day): Elemental Aid's second giver, and Before you go's Viewing Room Key, Postmaster Malown, Stratholme's Scarlet Key and Uldaman's Keystone (2026-11-05; drafted, to be checked)
	["Rau Cliffrunner (or Prate Cloudseer), Thousand Needles"] = "Rau Klippenläufer (oder Prate Cloudseer), Tausend Nadeln",
	["The Viewing Room Key"] = "Der Schlüssel zum Aussichtsraum",
	["Rattlegore drops the {item:13873:Viewing Room Key:1}. In the original game, it opened the Viewing Room door, the way on to Vectus and Marduk Blackpool, and one key did for the whole group. This is not yet checked on Forever."] = "Blutrippe lässt den {item:13873:Viewing Room Key:1} fallen. Im ursprünglichen Spiel öffnete er die Tür zum Aussichtsraum, den Weg zu Vectus und Marduk Pechschwarz, und ein Schlüssel reichte für die ganze Gruppe. Auf Forever ist das noch nicht geprüft.",
	["Postmaster Malown, a hidden boss"] = "Postmeister Malown, ein versteckter Boss",
	["The Stratholme Courier drops the city's postbox keys. In the original game, each locked postbox you opened brought out guards, and Postmaster Malown came with the third. This is not yet checked on Forever."] = "Der Kurier von Stratholme lässt die Briefkastenschlüssel der Stadt fallen. Im ursprünglichen Spiel kamen bei jedem verschlossenen Briefkasten, den Ihr öffnetet, Wachen heraus, und mit dem dritten kam Postmeister Malown. Auf Forever ist das noch nicht geprüft.",
	["{item:7146:The Scarlet Key:2} is in Doan's Strongbox, in the Scarlet Monastery's Library. In the original game, it also opened the Bastion Door and the door of the Hall of High Command here, and a rogue could pick both locks. This is not yet checked on Forever."] = "{item:7146:The Scarlet Key:2} liegt in Doans Geldkassette in der Bibliothek des Scharlachroten Klosters. Im ursprünglichen Spiel öffnete er hier auch die Tür der Bastion und die Tür der Halle des Oberkommandos, und ein Schurke konnte beide Schlösser knacken. Auf Forever ist das noch nicht geprüft.",
	["The Keystone"] = "Der Schlussstein",
	-- Uldaman's Keystone for both sides, reworded: the owner's report, 2026-11-05 (drafted, to be checked)
	["Revelosh drops {item:7741:The Shaft of Tsol:1}. Put together with the {item:7740:Gni'kiv Medallion} from Baelog's Chest, behind the Lost Dwarves, it makes the {item:7733:Staff of Prehistoria}, which works the Keystone in the Map Chamber, past Revelosh, and opens Ironaya's door. This is not yet checked on Forever."] = "Revelosh lässt {item:7741:The Shaft of Tsol:1} fallen. Zusammen mit dem {item:7740:Gni'kiv Medallion} aus Baelogs Truhe, hinter den verschollenen Zwergen, ergibt er den {item:7733:Staff of Prehistoria}, der den Schlussstein in der Kartenkammer hinter Revelosh bedient und Ironayas Tür öffnet. Auf Forever ist das noch nicht geprüft.",
}

-- The client's own names for the bosses, factions and places, which what it says of them (and the
-- routes the player saved) are matched by (Core/Registry.lua's ns.KeepClientNames).
if client then client.BOSS_NAMES, client.FACTION_NAMES, client.STRINGS = L.BOSS_NAMES, L.FACTION_NAMES, L.STRINGS end
